  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "The highest-transfer analogue had an unbound brain/unbound plasma AUC ratio of 0.08 in rats, directly demonstrating poor CNS penetration in a compound with amide, heteroaromatic, and nitrile features relevant to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "AZD6370, a close-transfer amide/heteroaromatic compound, showed no or low CNS levels by rat autoradiography, indicating insufficient blood-brain barrier penetration after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Compound 7z was undetectable in rat brain tissue after dosing, showing that an amide-linked heteroaromatic scaffold can be effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pyrazolopyridinone benzamide 3i gave a brain/plasma ratio below 0.08 in rats, a direct measure of poor brain exposure in a structurally related amide/chloro/heteroaromatic series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Methoxy analog 17 had a brain/plasma ratio of 0.19 in rats due to high P-gp efflux, illustrating that amide/nitrile-containing compounds can be efflux-limited at the BBB despite moderate lipophilicity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues uniformly show poor brain/CSF penetration, often due to efflux, and the query shares key amide, heteroaromatic, nitrile, and chloro features; therefore meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement for the query molecule itself.",
    "Exact efflux transporter profile of the query is not experimentally defined.",
    "Passive permeability and unbound brain exposure for the query are not directly measured."
  ],
